def _build_task_group_map(groups: list[WorkGroup]) -> tuple[dict[str, str], dict[str, WorkGroup], dict[str, list[str]]]:
    """Build lookup maps for task-to-group, group-by-id, and dependents adjacency."""
    task_group: dict[str, str] = {}
    by_id = {g.id: g for g in groups}
    dependents: dict[str, list[str]] = {g.id: [] for g in groups}
    for g in groups:
        for t in g.tasks:
            task_group[t.id] = g.id
        for d in g.depends_on:
            if d in dependents:
                dependents[d].append(g.id)
    return task_group, by_id, dependents


def _seed_stack(failing: set[str], task_group: dict[str, str]) -> list[str]:
    """Return group IDs for all failing tasks that have a known group."""
    return [task_group[t] for t in failing if t in task_group]


def _traverse_dependents(stack: list[str], by_id: dict[str, WorkGroup], dependents: dict[str, list[str]]) -> set[str]:
    """Walk the dependency graph from the stack, collecting all reachable task IDs."""
    out: set[str] = set(stack)
    seen: set[str] = set()
    while stack:
        gid = stack.pop()
        if gid in seen:
            continue
        seen.add(gid)
        for dep in dependents[gid]:
            for t in by_id[dep].tasks:
                out.add(t.id)
            stack.append(dep)
    return out"}
